    "name": "23 Opening of hearing",
    "text": "Section 23. Hearing Procedures for the Student Conduct Process1 All hearing participants are brought into the Board meeting room."
  },
  {
    "id": "c091",
    "name": "23.A Introductions",
    "text": "A. Chairperson invites all present to introduce themselves."
  },
  {
