  {
    "id": "c098",
    "name": "23.F Multiple accused presentations",
    "text": "In the event that there is more than one accused, the Board may bring them into the hearing room either individually or as a group for descriptions of the incident in alphabetical order; this system shall prevail throughout the remainder of the hearing procedures."
  },
  {
    "id": "c099",
    "name": "23.F.1 Accuser’s description",
